    "difficulty": "Moderate",
    "source": "Quantitative Aptitude (R.S. Aggarwal)",
    "question": "The annual grain yield $Y$ (in $\\text{kg/ha}$) and seasonal irrigation water applied $W$ (in $\\text{cm}$) for five experimental plots are given below:\n\n$$\\begin{array}{|c|c|c|}\n\\hline\n\\textbf{Plot} & \\textbf{Water Applied } W\\text{ (cm)} & \\textbf{Grain Yield } Y\\text{ (kg/ha)} \\\\\n\\hline\n\\text{P1} & 30 & 3600 \\\\\n\\text{P2} & 40 & 4400 \\\\\n\\text{P3} & 50 & 5000 \\\\\n\\text{P4} & 60 & 5400 \\\\\n\\text{P5} & 70 & 5600 \\\\\n\\hline\n\\end{array}$$\n\nCalculate the marginal water productivity in $\\text{kg/ha per cm of water}$ between Plot P1 and Plot P3. ________ (answer in integer).",
    "correct_answer": "70",
