    "source": "Quantitative Aptitude (R.S. Aggarwal) / Data Interpretation",
    "question": "The table below gives the revenue (in \text{Rs. } Lakhs) and expenditure (in \text{Rs. } Lakhs) of a state agro-processing corporation over four years:\n\n$$\\begin{array}{|c|c|c|}\n\\hline\n\\textbf{Year} & \\textbf{Revenue (\text{Rs. } Lakhs)} & \\textbf{Expenditure (\text{Rs. } Lakhs)} \\\\\n\\hline\n2020 & 400 & 320 \\\\\n2021 & 500 & 380 \\\\\n2022 & 600 & 450 \\\\\n2023 & 750 & 540 \\\\\n\\hline\n\\end{array}$$\n\nProfit is defined as $\\text{Revenue} - \\text{Expenditure}$, and Profit Margin as $\\frac{\\text{Profit}}{\\text{Revenue}} \\times 100\\%$. Which of the following statements is/are TRUE?",
