    "difficulty": "Moderate",
    "source": "A Modern Approach to Verbal & Non-Verbal Reasoning (R.S. Aggarwal)",
    "question": "Pointing to a photograph of a renowned soil chemist, Priya says: \"His mother is the only daughter of my maternal grandmother.\" How is the soil chemist related to Priya?",
