    "question": "A solid rectangular cuboid measuring $5\\text{ cm} \\times 4\\text{ cm} \\times 3\\text{ cm}$ is completely partitioned into identical small unit cubes of edge length $1\\text{ cm}$. How many total unit cubes are formed? ________ (answer in integer).",
