    "difficulty": "Easy",
    "source": "A Modern Approach to Verbal & Non-Verbal Reasoning (R.S. Aggarwal)",
    "question": "The net of a standard 6-faced die is unfolded as a cross shown below:\n\n```\n       +---+\n       | 1 |\n   +---+---+---+---+\n   | 2 | 3 | 4 | 5 |\n   +---+---+---+---+\n       | 6 |\n       +---+\n```\n\nWhen this net is folded into a cube, which face will be directly OPPOSITE to face 3?",
    "options": {
      "A": "5",
      "B": "4",
      "C": "6",
      "D": "1"
    },
    "correct_answer": "A",
    "solution": "**Method 1: Cube Net Alternation Rule**\nIn an unfolded 4-face strip net:\n1. Alternate faces along the straight strip are opposite each other: Face 2 is opposite Face 4, and Face 3 is opposite Face 5.\n2. The two projecting wing flaps are opposite each other: Face 1 is opposite Face 6.\nTherefore, Face 3 is directly opposite Face 5. Option **A** is correct."
